await (async(page)=>{
const checks=[];const check=(v,n)=>{if(!v)throw Error(n);checks.push(n)};
const name=page.getByRole('textbox',{name:/^Name/});
check(await name.getAttribute('aria-invalid')==='true','Required name invalid');check(await name.evaluate(e=>e===document.activeElement),'Invalid name focused');
await name.fill('Zoë Independent');await page.getByLabel('Email',{exact:true}).fill('invalid');
await page.getByRole('button',{name:'Create contact',exact:true}).click();
check(await page.getByLabel('Email',{exact:true}).getAttribute('aria-invalid')==='true','Invalid email marked');
await page.getByLabel('Email',{exact:true}).fill('');await page.getByLabel('Company',{exact:true}).fill('Fictional Verification');
await page.getByLabel('Notes',{exact:true}).fill('Independent create');
const button=page.getByRole('button',{name:'Create contact',exact:true});await button.scrollIntoViewIfNeeded();
const box=await button.boundingBox();check(box.height>=44&&box.width>=44,'Phone save target at least 44px');
await button.click();await page.getByRole('button',{name:'Save changes',exact:true}).waitFor();
await page.getByLabel('Notes',{exact:true}).fill('Independent edited persistence');
await page.getByRole('button',{name:'Save changes',exact:true}).click();await page.getByText(/Saved at/).waitFor();
await page.reload();await page.getByText('7 of 7 contacts').waitFor();
await page.getByRole('button',{name:/Zoë Independent/}).filter({visible:true}).click();
check(await page.getByLabel('Notes',{exact:true}).inputValue()==='Independent edited persistence','Create/edit persist after reload');
await page.getByRole('button',{name:'Delete',exact:true}).click();
await page.getByRole('alertdialog').getByRole('textbox').fill('Zoë Independent');
await page.getByRole('button',{name:'Delete contact',exact:true}).click();await page.getByText('6 of 6 contacts').waitFor();
check(await page.getByRole('button',{name:/Zoë Independent/}).count()===0,'Successful deletion removes trigger');
await page.reload();await page.getByText('6 of 6 contacts').waitFor();check(true,'Deleted fixture absent after reload; six seeds remain');
return {verdict:'PASS',checks,phoneSave:box};
})(page);
```
